/* =============================================================================
   FT GRAPHICS TOKENS — UK property-price web app
   Traced to: @financial-times/o-colors _palette.scss / _use-cases.scss,
              g-chartcolour v0.8.26, g-chartframe v5.3.3,
              ig.ft.com/visual-vocabulary/styles.css, g-axis v1.0.1
   ========================================================================== */

:root {
  /* ---- SURFACE -------------------------------------------------------- */
  --ft-paper:            #FFF1E5;  /* o-colors 'paper' — THE background */
  --ft-paper-box:        #F2DFCE;  /* o-colors 'wheat' — inset panel   */
  --ft-paper-band:       #FFFCFA;  /* banded rows behind ranked bars   */
  --ft-ink:              #000000;  /* chart title + the 60x4 black bar */

  /* ---- GREY RAMP (black mixed over paper — never a neutral grey) ------- */
  --ft-black-05:         #F2E5DA;
  --ft-black-10:         #E6D9CE;  /* value-axis gridlines             */
  --ft-black-20:         #CCC1B7;  /* category tick marks, muted bars  */
  --ft-black-30:         #B3A9A0;  /* 'then' series, context series    */
  --ft-black-40:         #999189;  /* zero / reference baseline        */
  --ft-black-50:         #807973;  /* derived                          */
  --ft-black-60:         #66605C;  /* subtitle, source, value labels   */
  --ft-black-70:         #4D4845;  /* axis labels, annotation text     */
  --ft-black-80:         #33302E;  /* body text                        */

  /* ---- TEXT ROLES ----------------------------------------------------- */
  --ft-text-title:       var(--ft-ink);        /* #000000 */
  --ft-text-body:        var(--ft-black-80);   /* #33302E */
  --ft-text-axis:        var(--ft-black-70);   /* #4D4845 */
  --ft-text-annotation:  var(--ft-black-70);   /* #4D4845 */
  --ft-text-subtitle:    var(--ft-black-60);   /* #66605C */
  --ft-text-source:      var(--ft-black-60);   /* #66605C */
  --ft-text-value-label: var(--ft-black-60);   /* #66605C */

  /* ---- STRUCTURE ------------------------------------------------------ */
  --ft-gridline:         var(--ft-black-10);   /* #E6D9CE  1px */
  --ft-tick:             var(--ft-black-20);   /* #CCC1B7  1px */
  --ft-baseline:         var(--ft-black-40);   /* #999189  1px */
  --ft-annotation-rule:  var(--ft-black-60);   /* #66605C  1px */
  --ft-gridline-width:   1px;
  --ft-baseline-width:   1px;
  --ft-line-width:       3px;
  --ft-axis-domain:      none;                 /* FT draws no axis line  */

  /* ---- SEMANTIC SERIES ------------------------------------------------ */
  --ft-primary:          #0F5499;  /* oxford  — 'now' / subject   6.90:1 */
  --ft-highlight:        #990F3D;  /* claret  — asset in focus    7.62:1 */
  --ft-secondary:        #0D7680;  /* teal                        4.84:1 */
  --ft-tertiary:         #593380;  /* velvet                      8.58:1 */
  --ft-muted:            #B3A9A0;  /* 'then' / context      fill only    */
  --ft-muted-light:      #CCC1B7;  /* de-emphasised bars    fill only    */
  --ft-positive:         #00994D;  /* jade    — price rise        3.35:1 */
  --ft-negative:         #CC0000;  /* crimson — price fall        5.32:1 */
  --ft-alert:            #FF8833;  /* mandarin — EPC / covenant  fill only */
  --ft-no-data-area:     #DAD2C3;
  --ft-no-data-line:     #B9B3A7;

  /* ---- CATEGORICAL, IN ORDER (FT line-web) ---------------------------- */
  --ft-cat-1: #0F5499; --ft-cat-2: #EB5E8D; --ft-cat-3: #70DCE6;
  --ft-cat-4: #9DBF57; --ft-cat-5: #208FCE; --ft-cat-6: #7F062E;
  --ft-cat-7: #C2B7AF; --ft-cat-8: #CE3140;

  /* ---- CATEGORICAL BARS, IN ORDER (FT categorical_bar) ---------------- */
  --ft-bar-1: #1E558C; --ft-bar-2: #94D2E6; --ft-bar-3: #1E8FCC;
  --ft-bar-4: #B3325D; --ft-bar-5: #FF75A3; --ft-bar-6: #D9CCC3;
  --ft-bar-7: #AECC70; --ft-bar-8: #F34D5B;

  /* ---- SEQUENTIAL (£ per sq ft intensity) ----------------------------- */
  --ft-seq-1: #F3DEC8; --ft-seq-2: #98C3CE; --ft-seq-3: #649EC1;
  --ft-seq-4: #3C78AE; --ft-seq-5: #0F5499;

  /* ---- DIVERGING (price change +/-; claret→oxford, NOT red→green) ----- */
  --ft-div-1: #B31147; --ft-div-2: #D75D79; --ft-div-3: #CEC6B9;
  --ft-div-4: #5884D6; --ft-div-5: #105BA6;

  /* ---- TYPOGRAPHY ----------------------------------------------------- */
  --ft-font: MetricWeb, Metric, "Helvetica Neue", Helvetica, -apple-system,
             BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  --ft-weight-regular:  400;   /* titles are 400 — NOT bold */
  --ft-weight-medium:   500;
  --ft-weight-semibold: 600;   /* section headings only */

  /* ---- TYPE SCALE — medium frame (700px), the app default ------------- */
  --ft-size-title:       24px;  --ft-lh-title:      28px;
  --ft-size-subtitle:    18px;  --ft-lh-subtitle:   20px;
  --ft-size-axis:        16px;
  --ft-size-annotation:  16px;
  --ft-size-label:       16px;
  --ft-size-legend:      16px;
  --ft-size-source:      14px;  --ft-lh-source:     16px;
  --ft-size-credit:      14px;  /* italic */

  /* ---- LAYOUT GEOMETRY (700 x 500 medium frame) ----------------------- */
  --ft-blackbar-w:       60px;
  --ft-blackbar-h:       4px;
  --ft-title-y:          32px;
  --ft-subtitle-y:       64px;
  --ft-text-x:           1px;    /* title/subtitle/source flush to graphic */
  --ft-margin-top:       100px;
  --ft-margin-left:      20px;
  --ft-margin-right:     24px;
  --ft-margin-bottom:    104px;
  --ft-source-offset:    44px;
}

/* ---- SMALL FRAME (<= 380px chart width) --------------------------------- */
@media (max-width: 480px) {
  :root {
    --ft-size-title: 20px;  --ft-lh-title: 24px;
    --ft-size-subtitle: 18px; --ft-lh-subtitle: 20px;
    --ft-size-axis: 14px; --ft-size-annotation: 14px;
    --ft-size-label: 14px; --ft-size-legend: 14px;
    --ft-size-source: 12px; --ft-lh-source: 12px;
    --ft-size-credit: 12px;
    --ft-margin-left: 15px; --ft-margin-bottom: 90px; --ft-source-offset: 38px;
  }
}

/* ---- LARGE FRAME (>= 1000px chart width) -------------------------------- */
@media (min-width: 1000px) {
  :root {
    --ft-size-title: 28px;  --ft-lh-title: 32px;
    --ft-size-subtitle: 18px; --ft-lh-subtitle: 20px;
    --ft-size-axis: 18px; --ft-size-annotation: 18px;
    --ft-size-label: 18px; --ft-size-legend: 18px;
    --ft-size-source: 16px; --ft-lh-source: 16px;
    --ft-size-credit: 16px;
    --ft-margin-bottom: 105px; --ft-source-offset: 44px;
  }
}

/* ---- DARK / SOCIAL VARIANT (FT socialframe) ----------------------------- */
:root[data-theme="dark"] {
  --ft-paper:           #333333;
  --ft-text-title:      #FFFFFF;
  --ft-text-axis:       #8E9095;
  --ft-text-subtitle:   #8E9095;
  --ft-text-source:     #8E9095;
  --ft-gridline:        #47494D;
  --ft-tick:            #47494D;
  --ft-baseline:        #8E9095;
  --ft-annotation-rule: #8E9095;
}

/* =============================================================================
   BASE CHART CSS
   ========================================================================== */
.ft-chart            { background: var(--ft-paper); font-family: var(--ft-font); }
.ft-chart svg text   { font-feature-settings: 'tnum' 1; -webkit-font-feature-settings: 'tnum'; }
.ft-chart .domain    { stroke-width: 0; }              /* no axis line, ever */
.ft-chart .black-bar { width: var(--ft-blackbar-w); height: var(--ft-blackbar-h); fill: var(--ft-ink); }

.ft-chart .chart-title    { font-size: var(--ft-size-title); font-weight: 400; fill: var(--ft-text-title); }
.ft-chart .chart-subtitle { font-size: var(--ft-size-subtitle); fill: var(--ft-text-subtitle); }
.ft-chart .chart-source   { font-size: var(--ft-size-source); fill: var(--ft-text-source); }
.ft-chart .chart-copyright{ font-size: var(--ft-size-credit); font-style: italic; fill: var(--ft-text-source); }

.ft-chart .yAxis text { font-size: var(--ft-size-axis); fill: var(--ft-text-axis); text-anchor: end; }
.ft-chart .xAxis text { font-size: var(--ft-size-axis); fill: var(--ft-text-axis); text-anchor: middle; }
.ft-chart .yAxis line { stroke: var(--ft-gridline); stroke-width: 1px; }
.ft-chart .xAxis line { stroke: var(--ft-tick);     stroke-width: 1px; }
.ft-chart .baseline line { stroke: var(--ft-baseline); stroke-width: 1px; stroke-dasharray: 1,0; }

.ft-chart .lines { stroke-width: 3px; stroke-linecap: square; stroke-linejoin: round; fill: none; }
.ft-chart .bars  { stroke: none; }
.ft-chart .highlights { fill: var(--ft-paper-band); }

.ft-chart .annotations-holder line,
.ft-chart .annotations-holder path { stroke: var(--ft-annotation-rule); stroke-width: 1px; fill: none; }
.ft-chart .annotations-holder text { font-size: var(--ft-size-annotation); fill: var(--ft-text-annotation); }
.ft-chart .legend, .ft-chart .highlight-label { font-size: var(--ft-size-legend); fill: var(--ft-text-value-label); }

/* =============================================================================
   TYPE SCALE — reference table (px)
   ---------------------------------------------------------------------------
   Role          | S (300w) | M (700w) | M-standalone | L (1180w)
   Title         | 20 / 24  | 24 / 28  | 28 / 28      | 28 / 32     (weight 400, #000000)
   Subtitle      | 18 / 20  | 18 / 20  | 24 / 28      | 18 / 20     (#66605C)
   Axis label    | 14       | 16       | 20           | 18          (#4D4845)
   Annotation    | 14       | 16       | 20           | 18          (#4D4845)
   Direct label  | 14       | 16       | 20           | 18          (#66605C)
   Legend        | 14       | 16       | 20           | 18          (#4D4845)
   Source        | 12 / 12  | 14 / 16  | 16 / 18      | 16 / 16     (#66605C)
   Credit        | 12 ital. | 14 ital. | 14 ital.     | 16 ital.    (#66605C)
   (size / line-height. Axis = annotation = direct label = legend, always.)
   ========================================================================== */

/* =============================================================================
   NUMBER FORMATTING — GBP
   ---------------------------------------------------------------------------
   AXIS (bare — the unit lives in the subtitle):
     divisor 1e3  -> ticks "0 200 400 600 800"   subtitle "£'000 per dwelling"
     divisor 1e6  -> ticks "0 1 2 3 4"           subtitle "£mn"
     divisor 1e9  -> ticks "0 5 10 15"           subtitle "£bn"
   Integer ticks: d3.format(',')   Non-integer: latch ONE precision across the
   whole axis by the span of the divided domain —
     span >= 0.5 -> '.1f' | < 0.5 -> '.2f' | <= 0.011 -> '.3f'
     < 0.0011 -> '.4f'    | < 0.00011 -> '.5f' | < 0.000011 -> '.6f'

   PROSE / TOOLTIP / ANNOTATION / TABLE (symbol returns):
     < £1mn        £950,000        (in full, comma separated — never £0.95mn)
     £1mn – £1bn   £1.2mn  £12.4mn  £340mn      ("mn", lowercase, closed up)
     >= £1bn       £3.4bn  £1.1tn
     Rates         5.25%  |  "per cent" spelled out in prose
     Per area      £42.50 per sq ft   (subtitle unit: "£ per sq ft")
   Never: £1.2m · £1.2M · £1.2MM · £1,200k · mixed magnitudes on one axis.
   ========================================================================== */

/* =============================================================================
   SOURCE LINE — exact wording convention (stacked lines, left-aligned, #66605C)
     *Excludes new-build and shared-ownership transactions
     Source: HM Land Registry Price Paid Data
     Graphic: Teddy James Advisory
   Several providers -> "Sources: HM Land Registry; ONS"
   Data vintage goes in the SUBTITLE, never in the source line.
   ========================================================================== */

